import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import { Button } from '../../../Button';
import {
  StyledOnlyActionContainer,
  StyledPageContainer,
  StyledPageDescription,
  StyledPageTitle,
  StyledTwoActionsContainer,
} from '../../EmptyState.styles';
import type { EmptyStatePageLevelProps } from '../../EmptyState.types';
import { getIllustration } from '../../utils';

export const PageLevel = React.forwardRef<
  HTMLDivElement,
  EmptyStatePageLevelProps
>(
  (
    {
      title,
      description,
      actions,
      customIlustration,
      ilustrationName = 'beesAlert',
      className,
      ...props
    },
    forwardedRef,
  ) => {
    const illustration = getIllustration(customIlustration, ilustrationName);
    const onlyAction = actions?.length === 1 ? actions[0] : null;
    const twoActions = actions?.length === 2;

    return (
      <StyledPageContainer
        {...omitTransientProps(props)}
        ref={forwardedRef}
        className={className}
      >
        <img
          alt={illustration.alt}
          height={illustration.height}
          src={illustration.src}
          width={illustration.width}
        />
        {title ? <StyledPageTitle>{title}</StyledPageTitle> : null}
        {description ? (
          <StyledPageDescription>{description}</StyledPageDescription>
        ) : null}
        {onlyAction ? (
          <StyledOnlyActionContainer>
            <Button
              key={onlyAction.name}
              type="button"
              onClick={onlyAction.action}
              variant={onlyAction.variant}
            >
              {onlyAction.name}
            </Button>
          </StyledOnlyActionContainer>
        ) : null}
        {twoActions ? (
          <StyledTwoActionsContainer>
            {actions.map((action) => (
              <Button
                key={action.name}
                type="button"
                onClick={action.action}
                variant={action.variant}
              >
                {action.name}
              </Button>
            ))}
          </StyledTwoActionsContainer>
        ) : null}
      </StyledPageContainer>
    );
  },
);

PageLevel.displayName = 'EmptyState.PageLevel';
